```python
import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be positive")
    records = []
    system = platform.system()
    start_time = time.time()
    while True:
        now = time.time()
        if now - start_time >= duration and records:
            break
        cpu_usage = None
        if system == "Windows":
            try:
                cmd = [
                    "powershell",
                    "-Command",
                    "(Get-Counter '\\Processor(_Total)\\% Processor Time').CounterSamples[0].CookedValue"
                ]
                output = subprocess.check_output(cmd, stderr=subprocess.STDOUT, text=True)
                cpu_usage = float(output.strip())
            except Exception:
                cpu_usage = None
        else:
            try:
                cmd = ["mpstat", "1", "1"]
                output = subprocess.check_output(cmd, stderr=subprocess.STDOUT, text=True)
                lines = output.strip().splitlines()
                idle = None
                for line in lines[::-1]:
                    parts = line.split()
                    if len(parts) > 3 and (parts[0].isdigit() or parts[0] == "all" or parts[2] == "all"):
                        try:
                            idle = float(parts[-1])
                            break
                        except ValueError:
                            continue
                if idle is not None:
                    cpu_usage = 100.0 - idle
            except Exception:
                try:
                    cmd = ["sh", "-c", "top -b -n1 | grep 'Cpu' || top -b -n1 | head -n5"]
                    output = subprocess.check_output(cmd, stderr=subprocess.STDOUT, text=True)
                    line = ""
                    for l in output.splitlines():
                        if "Cpu(s)" in l or "Cpu" in l:
                            line = l
                            break
                    idle = None
                    if "%" in line:
                        for token in line.replace(",", " ").split():
                            if "id" in token:
                                continue
                        parts = line.replace(",", " ").split()
                        for i, token in enumerate(parts):
                            if token.lower().startswith("id"):
                                try:
                                    idle = float(parts[i - 1])
                                except Exception:
                                    idle = None
                                break
                        if idle is None:
                            for token in parts:
                                if token.endswith("id"):
                                    try:
                                        idle = float(token[:-2])
                                    except Exception:
                                        idle = None
                                    break
                    if idle is not None:
                        cpu_usage = 100.0 - idle
                except Exception:
                    cpu_usage = None
        record = {
            "timestamp": now,
            "cpu_usage": cpu_usage
        }
        records.append(record)
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as f:
            json.dump(records, f)
    except IOError:
        return None
    return LOGFILE_PATH
```

